package gregtech.content.registry;
import gregtech.content.block.BookShelfBlock;import gregtech.content.book.BookShelfVariants;import net.minecraft.world.level.block.*;import net.minecraft.world.level.block.state.BlockBehaviour;import net.minecraft.world.level.material.MapColor;
public final class GTBookShelves {private GTBookShelves(){}private static final java.util.Map<String,RegisteredBlock<BookShelfBlock>> ALL=new java.util.LinkedHashMap<>();public static java.util.Collection<RegisteredBlock<BookShelfBlock>> all(){return java.util.List.copyOf(ALL.values());}public static BookShelfBlock get(String id){return ALL.get(id).get();}public static void initialize(){for(var v:BookShelfVariants.all()){var b=RegisteredBlock.registerBlock(v.path(),()->new BookShelfBlock(BlockBehaviour.Properties.of().mapColor(v.metal()?MapColor.METAL:MapColor.WOOD).strength(v.hardness(),v.resistance()).requiresCorrectToolForDrops().sound(v.metal()?SoundType.METAL:SoundType.WOOD),v));ALL.put(v.path(),b);GTBlocks.BLOCK_ITEMS.register(v.path(),()->new gregtech.content.item.BookShelfBlockItem(b.get(),new net.minecraft.world.item.Item.Properties().stacksTo(16)));}}}
